// One-off seed for the 10 launch articles of the Syrama Yachting blog.
// Writes to `yachting_blog_post` (NOT `blog_post` — see schema.prisma).
// Idempotent: upserts by slug, so re-running edits in place rather than
// duplicating. Run once with:  node prisma/seed-blog.mjs
import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

function readingMinutes(content) {
  const words = content.reduce((n, b) => {
    if (b.type === 'list') return n + b.items.join(' ').split(/\s+/).length
    if (b.text) return n + b.text.split(/\s+/).length
    return n
  }, 0)
  return Math.max(1, Math.round(words / 200))
}

const P = (text) => ({ type: 'paragraph', text })
const H = (text) => ({ type: 'heading', text })
const L = (items) => ({ type: 'list', items })
const Q = (text, attribution) => ({ type: 'quote', text, ...(attribution ? { attribution } : {}) })

